android.extraProguardRules:
# --- Run 4.1: v1.0.0 crashed at launch (R8) ---
# WorkManager arrives via react-native-maps (androidx.work:work-runtime). It starts
# from androidx.startup.InitializationProvider and creates its Room database
# (WorkDatabase_Impl) by reflection, which R8 renamed/removed.
-keep class androidx.work.** { *; }
-keepnames class androidx.work.impl.WorkDatabase
-keep class androidx.startup.** { *; }
-keep class * implements androidx.startup.Initializer { <init>(); }
-keep class androidx.room.** { *; }
-keep class * extends androidx.room.RoomDatabase { *; }
-keep class **_Impl { *; }
-dontwarn androidx.work.**
# react-native-maps / Google Maps
-keep class com.rnmaps.** { *; }
-keep class com.google.android.gms.maps.** { *; }
# Expo modules are registered by name
-keep class expo.modules.** { *; }
